# So repo-memory's hooks fire on EVERY workspace right now — PreInvocation, PreToolUse, PostToolUse, Stop
# That's the overhead the proposed architecture eliminates
# Let me check how many tool calls repo-memory hooks intercept per workspace
cat /Users/mcneillm/.gemini/config/plugins/repo-memory/hooks.json | python3 -c "
import json, sys
hooks = json.load(sys.stdin)
for name, hook in hooks.items():
    for event in hook:
        if event == 'PreToolUse':
            for entry in hook[event]:
                print(f'  PreToolUse matcher: {entry.get(\"matcher\", \"*\")}')
        elif event == 'PostToolUse':
            for entry in hook[event]:
                print(f'  PostToolUse matcher: {entry.get(\"matcher\", \"*\")}')
"

