#!/usr/bin/env python3
"""Fetch PR #291 files from GitHub API."""
import subprocess, json, base64

def fetch_file(path, ref="chore/migrate-bug-fixer-to-daemon-plugin"):
    r = subprocess.run(
        ['gh', 'api', f'repos/matthewmcneill/esp32-app-foundation/contents/{path}?ref={ref}'],
        capture_output=True, text=True
    )
    if r.returncode != 0:
        return f"ERROR: {r.stderr}"
    data = json.loads(r.stdout)
    return base64.b64decode(data['content']).decode()

for f in ['.agents/plugins.json', '.agents/hooks.json', '.gitmodules']:
    print(f"=== {f} ===")
    print(fetch_file(f))
    print()

